cat > dates.js <<'EOF'
export function isLeapYear(y) { return y % 4 === 0 && y % 100 !== 0; }
export function daysInMonth(year, month) { const days = [31,28,31,30,31,30,31,31,30,31,30,31]; if (month === 2 && isLeapYear(year)) return 29; return days[month]; }
export function dayOfYear(s) { const [y, m, d] = s.split('-').map(Number); let t = d; for (let i = 1; i < m; i++) t += daysInMonth(y, i); return t; }
EOF
cat > dates.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { isLeapYear, daysInMonth, dayOfYear } from './dates.js';

test('isLeapYear', () => {
  assert.equal(isLeapYear(2024), true);
  assert.equal(isLeapYear(1900), false);
  assert.equal(isLeapYear(2000), true);
});

test('daysInMonth', () => {
  assert.equal(daysInMonth(2023, 1), 31);
  assert.equal(daysInMonth(2024, 2), 29);
  assert.equal(daysInMonth(2023, 12), 31);
});

test('dayOfYear', () => {
  assert.equal(dayOfYear('2024-03-01'), 61);
  assert.equal(dayOfYear('2023-12-31'), 365);
});
EOF
